(() => {
  'use strict';
  const VERSION = 'reflection-cover-animation-20260807-1';
  const surfaces = [...document.querySelectorAll('[data-reflection-cover-demo]')];
  const mediaQueries = [window.matchMedia('(hover: hover) and (pointer: fine)'), window.matchMedia('(min-width: 701px)'), window.matchMedia('(prefers-reduced-motion: no-preference)')];
  const eligible = () => mediaQueries.every((query) => query.matches) && !navigator.connection?.saveData;
  if (!surfaces.length) return;
  const setup = (surface) => {
    const canvas = surface.querySelector('[data-reflection-cover-canvas]');
    const image = surface.querySelector('img');
    if (!canvas || !image) return null;
    const ctx = canvas.getContext('2d', { alpha: true });
    if (!ctx) return null;
    surface.dataset.reflectionCoverVersion = VERSION;
    let frame = 0;
    let running = false;
    let visible = false;
    const pointer = { x: 0.5, y: 0.46, targetX: 0.5, targetY: 0.46 };
    const size = () => {
      const rect = surface.getBoundingClientRect();
      const dpr = Math.min(window.devicePixelRatio || 1, 1.5);
      const width = Math.max(1, Math.round(rect.width * dpr));
      const height = Math.max(1, Math.round(rect.height * dpr));
      if (canvas.width !== width || canvas.height !== height) { canvas.width = width; canvas.height = height; }
      canvas.style.width = `${rect.width}px`;
      canvas.style.height = `${rect.height}px`;
      return { width, height };
    };
    const draw = (time) => {
      if (!running || !eligible() || !visible) { frame = 0; ctx.clearRect(0, 0, canvas.width, canvas.height); return; }
      const { width, height } = size();
      pointer.x += (pointer.targetX - pointer.x) * 0.055;
      pointer.y += (pointer.targetY - pointer.y) * 0.055;
      const phase = (time % 6200) / 6200;
      const wave = Math.sin(phase * Math.PI * 2);
      ctx.clearRect(0, 0, width, height);
      ctx.globalCompositeOperation = 'screen';
      ctx.globalAlpha = 0.62;
      const centerX = width * (0.18 + pointer.x * 0.72 + wave * 0.025);
      const centerY = height * (0.16 + pointer.y * 0.60 + Math.cos(phase * Math.PI * 2) * 0.018);
      const gradient = ctx.createLinearGradient(centerX - width * 0.38, centerY + height * 0.32, centerX + width * 0.36, centerY - height * 0.34);
      gradient.addColorStop(0.00, 'rgba(255,255,255,0)');
      gradient.addColorStop(0.38, 'rgba(255,255,255,0)');
      gradient.addColorStop(0.47, 'rgba(255,236,177,0.32)');
      gradient.addColorStop(0.52, 'rgba(255,255,255,0.55)');
      gradient.addColorStop(0.58, 'rgba(245,153,86,0.20)');
      gradient.addColorStop(0.72, 'rgba(255,255,255,0)');
      ctx.fillStyle = gradient;
      ctx.save();
      ctx.translate(centerX, centerY);
      ctx.rotate(-0.32 + wave * 0.035);
      ctx.translate(-centerX, -centerY);
      ctx.filter = `blur(${Math.max(10, width * 0.014)}px)`;
      ctx.fillRect(-width * 0.12, -height * 0.18, width * 1.24, height * 1.36);
      ctx.restore();
      const glint = ctx.createRadialGradient(centerX, centerY, 0, centerX, centerY, Math.min(width, height) * 0.34);
      glint.addColorStop(0, 'rgba(255,255,255,0.20)');
      glint.addColorStop(0.34, 'rgba(255,210,146,0.16)');
      glint.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.filter = 'blur(4px)';
      ctx.fillStyle = glint;
      ctx.fillRect(0, 0, width, height);
      ctx.globalAlpha = 1;
      ctx.globalCompositeOperation = 'source-over';
      surface.style.setProperty('--reflection-x', `${Math.round(pointer.x * 100)}%`);
      surface.style.setProperty('--reflection-y', `${Math.round(pointer.y * 100)}%`);
      frame = requestAnimationFrame(draw);
    };
    const start = () => { if (running || !eligible() || !visible) return; running = true; frame = requestAnimationFrame(draw); };
    const stop = () => { running = false; if (frame) cancelAnimationFrame(frame); frame = 0; ctx.clearRect(0, 0, canvas.width, canvas.height); };
    const sync = () => eligible() && visible ? start() : stop();
    const move = (event) => {
      const rect = surface.getBoundingClientRect();
      pointer.targetX = Math.min(1, Math.max(0, (event.clientX - rect.left) / rect.width));
      pointer.targetY = Math.min(1, Math.max(0, (event.clientY - rect.top) / rect.height));
      sync();
    };
    const observer = new IntersectionObserver((entries) => { visible = entries.some((entry) => entry.isIntersecting); sync(); }, { threshold: 0.08 });
    observer.observe(surface);
    surface.addEventListener('pointermove', move, { passive: true });
    surface.addEventListener('pointerleave', () => { pointer.targetX = 0.5; pointer.targetY = 0.46; });
    mediaQueries.forEach((query) => query.addEventListener('change', sync));
    window.addEventListener('resize', sync, { passive: true });
    document.addEventListener('visibilitychange', sync);
    if (image.complete) sync(); else image.addEventListener('load', sync, { once: true });
    return { stop };
  };
  const instances = surfaces.map(setup).filter(Boolean);
  window.addEventListener('pagehide', () => instances.forEach((instance) => instance.stop()));
})();
